lass=&quot;NormalTextRun SCXW21924362 BCX0&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW21924362 BCX0&quot;&gt;and other markets.&amp;nbsp;&lt;/span&gt;&lt;span class=&quot;NormalTextRun SpellingErrorV2Themed SCXW21924362 BCX0&quot;&gt;IDnow&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW21924362 BCX0&quot;&gt;&amp;nbsp;provides GenAI&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW21924362 BCX0&quot;&gt;-&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW21924362 BCX0&quot;&gt;enabled tooling and expects responsible, compliant use.&lt;/span&gt;&lt;/span&gt;&lt;span class=&quot;EOP SCXW21924362 BCX0&quot; data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;&lt;strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Business outcome ownership&lt;/span&gt;&lt;/strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;: define measurable goals and KPIs (adoption, quality, satisfaction) and drive outcome-oriented delivery.&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
